import {poses} from './model.mjs';import {createScene} from './scene.mjs';
export default {id:'migrated-basic-dial',capabilities:{detail:['compact','standard']},initialState:poses.rest,poses,createScene,clientEntry:new URL('./client.mjs',import.meta.url),render(args){const s=createScene(args);try{const m=s.update(args.state);return {renderer:'three-illustration',viewBox:[0,0,600,400],body:`<g data-scene="three">${s.render()}</g><text class="reading" data-part="static-readout" x="24" y="366">${m.reading}</text>`,title:'Sliding-block dial indicator',description:'Hover or drag to slide three gauge blocks of heights 18, 14 and 10 drawing pixels. The probe follows the overlapping block; one needle revolution is 20 pixels. Arrow keys choose blocks. An illustrative model, not calibration.'};}finally{s.dispose();}}};
